#include <iostream>
#include <vector>
using namespace std;

const long long MOD = 1000000007LL;

long long solve(int n, vector<int>& level) {
    int left = 0;
    int right = n - 1;
    int value = 1;

    // 从两端向中间依次放置较小等级
    while (left <= right) {
        level[left] = value;
        value++;

        if (left != right) {
            level[right] = value;
            value++;
        }

        left++;
        right--;
    }

    long long ans = 0;

    for (int i = 0; i < n; i++) {
        long long weight = 1LL * (i + 1) * (n - i);
        ans = (ans + (weight % MOD) * level[i]) % MOD;
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> level(n);

    long long ans = solve(n, level);

    cout << ans << '\n';

    for (int i = 0; i < n; i++) {
        if (i > 0) {
            cout << ' ';
        }
        cout << level[i];
    }
    cout << '\n';

    return 0;
}
